/* selectMasterMdCtCorpGroupManageList */ SELECT CORP_CODE ,CORP_NAME ,GROUP_CODE ,GROUP_NAME ,ADD_USER_ID ,ADD_DATE ,CHANGE_DATE ,CHANGE_USER_ID ,USE_FLAG FROM BNTBUYERGROUP WHERE GROUP_FLAG = 'B'
AND CORP_NAME LIKE '%' || #{st_corp_name} || '%'
ORDER BY SORT_SEQ, GROUP_CODE

