/* updateMasterMdCtCorpGroupManageList */
UPDATE BNTBUYERGROUP					
SET
	CORP_NAME			= #{CORP_NAME} 	
	,GROUP_CODE		= #{GROUP_CODE}
	,GROUP_NAME		= #{GROUP_NAME}
	,USE_FLAG			= #{USE_FLAG}
	,CHANGE_DATE		= TO_CHAR(SYSDATE, 'YYYY/MM/DD')
	,CHANGE_USER_ID	= #{st_user_id}
 WHERE CORP_CODE	= #{CORP_CODE}


/* insertMasterMdCtCorpGroupManageList */
