(
	CORP_CODE
	,CORP_NAME 	
	,GROUP_CODE
	,GROUP_NAME
	,GROUP_FLAG
	,USE_FLAG
	,ADD_USER_ID
	,ADD_DATE
) VALUES (									
	#{CORP_CODE}
	,#{CORP_NAME}
	,#{GROUP_CODE}
	,#{GROUP_NAME}
	,'B'
	,#{USE_FLAG}
	,#{st_user_id}
	,TO_CHAR(SYSDATE, 'YYYY/MM/DD')
)


